// High school intro history & civics quizzes — hs01 through hs15
export const HS_HISTORY_CIVICS_QUIZZES = [
  { id:'hs01', cat:'Behavioral & Social Sciences', title:`US Government Basics: Branches of Government`, diff:'Easy', qs:[
      { q:`Which branch of the US government is responsible for making laws?`, ch:[`Executive`,`Legislative`,`Judicial`,`Administrative`], ans:1, exp:`The Legislative branch, made up of Congress (the House and Senate), writes and passes laws.` },
      { q:`Who is the head of the Executive branch?`, ch:[`The Chief Justice`,`The Speaker of the House`,`The President`,`The Senate Majority Leader`], ans:2, exp:`The President leads the Executive branch, which enforces and carries out the laws.` },
      { q:`Which branch of government interprets laws and decides if they are constitutional?`, ch:[`Legislative`,`Executive`,`Judicial`,`Regulatory`], ans:2, exp:`The Judicial branch, headed by the Supreme Court, interprets laws and rules on their constitutionality.` },
      { q:`Why did the framers of the Constitution divide the government into three branches?`, ch:[`To make the government run faster`,`To prevent any one branch from becoming too powerful`,`To reduce the cost of government`,`To give more power to the states`], ans:1, exp:`Checks and balances split power among branches so no single branch can dominate the others.` },
      { q:`How many branches does the US federal government have?`, ch:[`Two`,`Three`,`Four`,`Five`], ans:1, exp:`The US government has three branches: Legislative, Executive, and Judicial.` },
      { q:`Congress is made up of which two chambers?`, ch:[`The House of Representatives and the Senate`,`The Cabinet and the Senate`,`The House of Lords and the House of Commons`,`The Senate and the Supreme Court`], ans:0, exp:`Congress is bicameral, meaning it has two chambers: the House of Representatives and the Senate.` },
      { q:`What is the length of a US President's term of office?`, ch:[`2 years`,`4 years`,`6 years`,`8 years`], ans:1, exp:`A US President serves a four-year term and may be elected to a maximum of two terms.` },
      { q:`How many justices currently sit on the US Supreme Court?`, ch:[`5`,`7`,`9`,`11`], ans:2, exp:`The Supreme Court has nine justices: one Chief Justice and eight Associate Justices.` },
      { q:`What is it called when the President refuses to sign a bill passed by Congress into law?`, ch:[`A veto`,`A filibuster`,`An impeachment`,`A subpoena`], ans:0, exp:`A veto is the President's power to reject a bill. Congress can still override a veto with enough votes.` },
      { q:`What vote is required for Congress to override a presidential veto?`, ch:[`A simple majority in the House only`,`A two-thirds vote in both the House and Senate`,`A unanimous vote in the Senate`,`A majority vote of state governors`], ans:1, exp:`Overriding a veto requires a two-thirds vote in both the House and the Senate.` },
      { q:`The power of courts to strike down a law as unconstitutional is known as:`, ch:[`Judicial review`,`Executive privilege`,`Legislative override`,`Due process`], ans:0, exp:`Judicial review lets courts declare laws unconstitutional; it was established by the Supreme Court in Marbury v. Madison (1803).` },
      { q:`The system that divides power among the three branches so each can limit the others is called:`, ch:[`Federalism`,`Checks and balances`,`Popular sovereignty`,`Bicameralism`], ans:1, exp:`Checks and balances lets each branch limit the power of the other two, keeping the government balanced.` },
    ]
  },
  { id:'hs02', cat:'Behavioral & Social Sciences', title:`The US Constitution & Bill of Rights`, diff:'Easy', qs:[
      { q:`In what city was the US Constitution written in 1787?`, ch:[`New York City`,`Boston`,`Philadelphia`,`Washington, DC`], ans:2, exp:`Delegates met at the Constitutional Convention in Philadelphia in the summer of 1787 to draft the Constitution.` },
      { q:`The Preamble to the Constitution begins with which famous phrase?`, ch:[`"Four score and seven years ago"`,`"We the People"`,`"When in the Course of human events"`,`"Life, Liberty, and the pursuit of Happiness"`], ans:1, exp:`The Preamble opens with "We the People," establishing that government authority comes from the citizens.` },
      { q:`What is the common name for the first ten amendments to the Constitution?`, ch:[`The Articles of Confederation`,`The Federalist Papers`,`The Bill of Rights`,`The Declaration of Rights`], ans:2, exp:`The first ten amendments, ratified in 1791, are known as the Bill of Rights and protect individual freedoms.` },
      { q:`Which freedoms are protected by the First Amendment?`, ch:[`The right to bear arms`,`Speech, religion, press, assembly, and petition`,`Protection against unreasonable searches`,`The right to a speedy trial`], ans:1, exp:`The First Amendment protects freedom of speech, religion, the press, peaceful assembly, and the right to petition the government.` },
      { q:`The Second Amendment primarily addresses:`, ch:[`Freedom of the press`,`The right to a jury trial`,`The right to keep and bear arms`,`Protection from cruel punishment`], ans:2, exp:`The Second Amendment protects the right of citizens to keep and bear arms.` },
      { q:`The Fourth Amendment protects citizens from:`, ch:[`Double jeopardy`,`Unreasonable searches and seizures`,`Excessive bail`,`Self-incrimination`], ans:1, exp:`The Fourth Amendment guards against unreasonable searches and seizures of people, homes, and property, generally requiring a warrant.` },
      { q:`The Fifth Amendment includes protection against:`, ch:[`Being forced to testify against yourself`,`Cruel and unusual punishment`,`Unlawful searches`,`Denial of a speedy trial`], ans:0, exp:`The Fifth Amendment protects against self-incrimination and guarantees due process of law.` },
      { q:`As of today, how many total amendments does the US Constitution have?`, ch:[`10`,`19`,`27`,`33`], ans:2, exp:`The Constitution currently has 27 amendments, including the original ten in the Bill of Rights.` },
      { q:`Which amendment abolished slavery in the United States?`, ch:[`12th Amendment`,`13th Amendment`,`14th Amendment`,`15th Amendment`], ans:1, exp:`The 13th Amendment, ratified in 1865, abolished slavery throughout the United States.` },
      { q:`Which amendment guaranteed women the right to vote?`, ch:[`15th Amendment`,`17th Amendment`,`19th Amendment`,`21st Amendment`], ans:2, exp:`The 19th Amendment, ratified in 1920, guaranteed women the right to vote nationwide.` },
      { q:`How can the Constitution be amended?`, ch:[`The President signs an executive order`,`A proposal by two-thirds of Congress (or a national convention) and ratification by three-fourths of the states`,`A simple majority vote of the Supreme Court`,`A unanimous vote of state governors`], ans:1, exp:`Amendments require proposal by two-thirds of Congress (or a convention called by the states) and ratification by three-fourths of the states.` },
      { q:`Federalism refers to:`, ch:[`Rule by a single political party`,`The division of power between the national government and the states`,`The separation of church and state`,`Direct democracy at the local level`], ans:1, exp:`Federalism is a system where power is divided and shared between the national (federal) government and individual state governments.` },
    ]
  },
  { id:'hs03', cat:'Behavioral & Social Sciences', title:`Colonial America & the Road to Revolution`, diff:'Easy', qs:[
      { q:`What was the first permanent English colony in North America?`, ch:[`Plymouth`,`Jamestown`,`Boston`,`Charleston`], ans:1, exp:`Jamestown, Virginia, founded in 1607, was the first permanent English settlement in North America.` },
      { q:`The Pilgrims who landed at Plymouth in 1620 traveled aboard which ship?`, ch:[`The Santa Maria`,`The Mayflower`,`The Nina`,`The Constitution`], ans:1, exp:`The Pilgrims sailed on the Mayflower and landed near Plymouth, Massachusetts, in 1620.` },
      { q:`The Mayflower Compact is significant because it:`, ch:[`Declared independence from Britain`,`Was an early agreement for self-government among colonists`,`Ended the French and Indian War`,`Established the first American currency`], ans:1, exp:`The Mayflower Compact was a basic agreement in which the Pilgrims agreed to govern themselves and make decisions by majority rule.` },
      { q:`The triangular trade connected which three regions?`, ch:[`Europe, Africa, and the Americas`,`Asia, Europe, and Australia`,`North America, South America, and Antarctica`,`Britain, France, and Spain`], ans:0, exp:`The triangular trade linked Europe, Africa, and the Americas, and included the transport and enslavement of African people.` },
      { q:`The French and Indian War (1754-1763) was fought mainly between:`, ch:[`Britain and Spain`,`France and Spain`,`Britain and France, each with Native American allies`,`The colonies and Britain`], ans:2, exp:`The French and Indian War pitted Britain against France, each supported by different Native American allies, for control of North American territory.` },
      { q:`The Stamp Act of 1765 required colonists to:`, ch:[`Pay a tax on printed materials like newspapers and legal documents`,`House British soldiers in their homes`,`Give up their right to trial by jury`,`Pay a tax on tea only`], ans:0, exp:`The Stamp Act taxed printed goods such as newspapers, legal documents, and playing cards, angering colonists.` },
      { q:`The slogan "No taxation without representation" expressed colonial anger over:`, ch:[`High prices for imported goods`,`Being taxed by a Parliament in which they had no elected voice`,`The cost of building roads`,`Restrictions on colonial farming`], ans:1, exp:`Colonists objected to Britain taxing them without allowing colonial representatives to vote in Parliament.` },
      { q:`The Boston Massacre of 1770 involved:`, ch:[`Colonists burning British tea`,`British soldiers killing several colonists during a confrontation`,`A colonial victory over French forces`,`The signing of a peace treaty`], ans:1, exp:`British soldiers fired into a crowd of colonists in Boston, killing five, which fueled anti-British sentiment.` },
      { q:`During the Boston Tea Party of 1773, colonists:`, ch:[`Signed a formal declaration of war`,`Dumped British tea into Boston Harbor to protest the Tea Act`,`Elected their first governor`,`Burned down a British fort`], ans:1, exp:`Colonists dressed as Mohawk Indians boarded ships and dumped chests of tea into Boston Harbor to protest taxation and British trade policy.` },
      { q:`Britain's harsh response to the Boston Tea Party, which closed Boston's port, was known to colonists as:`, ch:[`The Navigation Acts`,`The Intolerable Acts`,`The Townshend Acts`,`The Proclamation of 1763`], ans:1, exp:`Colonists called Britain's punitive laws the "Intolerable Acts" because they severely restricted Massachusetts' self-government and trade.` },
      { q:`The First Continental Congress, held in 1774, brought together:`, ch:[`Delegates from twelve of the thirteen colonies to discuss a unified response to Britain`,`British generals planning colonial defense`,`Representatives from France and Spain`,`State governors after independence`], ans:0, exp:`Delegates from most of the colonies met in Philadelphia in 1774 to coordinate a response to British policies.` },
      { q:`How many original British colonies later became the United States?`, ch:[`10`,`13`,`15`,`20`], ans:1, exp:`There were 13 original British colonies along the Atlantic coast of North America.` },
    ]
  },
  { id:'hs04', cat:'Behavioral & Social Sciences', title:`The American Revolution`, diff:'Easy', qs:[
      { q:`Which battles are often called the "shot heard round the world," marking the war's start in 1775?`, ch:[`Bunker Hill and Trenton`,`Lexington and Concord`,`Saratoga and Yorktown`,`Brandywine and Valley Forge`], ans:1, exp:`The battles of Lexington and Concord in April 1775 were the first military engagements of the American Revolution.` },
      { q:`The Second Continental Congress appointed whom as commander of the Continental Army?`, ch:[`Thomas Jefferson`,`Benjamin Franklin`,`George Washington`,`John Adams`], ans:2, exp:`The Second Continental Congress selected George Washington to lead the Continental Army in 1775.` },
      { q:`On what date was the Declaration of Independence adopted?`, ch:[`July 4, 1776`,`March 15, 1775`,`September 3, 1783`,`December 25, 1776`], ans:0, exp:`The Continental Congress formally adopted the Declaration of Independence on July 4, 1776.` },
      { q:`Who is credited as the primary author of the Declaration of Independence?`, ch:[`John Adams`,`Thomas Jefferson`,`Benjamin Franklin`,`Alexander Hamilton`], ans:1, exp:`Thomas Jefferson drafted most of the Declaration of Independence, though a committee reviewed and revised it.` },
      { q:`Thomas Paine's pamphlet "Common Sense" was influential because it:`, ch:[`Argued for reconciliation with Britain`,`Made a persuasive, widely-read case for American independence`,`Established the first US bank`,`Proposed the Bill of Rights`], ans:1, exp:`"Common Sense" (1776) used plain language to persuade many colonists that independence from Britain was the right path.` },
      { q:`Which nation formally allied with the Americans after the Battle of Saratoga?`, ch:[`Spain`,`France`,`Prussia`,`The Netherlands`], ans:1, exp:`The American victory at Saratoga in 1777 convinced France to formally ally with the colonies, providing crucial troops and naval support.` },
      { q:`The winter encampment of 1777-1778, where Washington's army suffered hardship but trained and regrouped, was at:`, ch:[`Valley Forge`,`Yorktown`,`Trenton`,`Bunker Hill`], ans:0, exp:`At Valley Forge, Pennsylvania, the Continental Army endured a harsh winter while training under Baron von Steuben.` },
      { q:`The last major battle of the American Revolution, where British General Cornwallis surrendered, was at:`, ch:[`Saratoga`,`Yorktown`,`Concord`,`Trenton`], ans:1, exp:`The 1781 Battle of Yorktown ended with Cornwallis's surrender, effectively securing American independence.` },
      { q:`Which treaty formally ended the American Revolutionary War in 1783?`, ch:[`The Treaty of Ghent`,`The Treaty of Paris`,`The Treaty of Versailles`,`The Treaty of Utrecht`], ans:1, exp:`The Treaty of Paris (1783) ended the war and formally recognized the United States as an independent nation.` },
      { q:`The first framework of national government for the United States, adopted before the Constitution, was called:`, ch:[`The Bill of Rights`,`The Federalist Papers`,`The Articles of Confederation`,`The Mayflower Compact`], ans:2, exp:`The Articles of Confederation (1781) created a weak central government and were later replaced by the Constitution.` },
      { q:`A key weakness of the government under the Articles of Confederation was that it:`, ch:[`Had no power to enforce laws or collect taxes effectively`,`Had a king with too much power`,`Banned all state governments`,`Gave the President too much authority`], ans:0, exp:`Congress under the Articles could not effectively tax or enforce laws, leaving the national government very weak.` },
      { q:`Which French nobleman volunteered to fight alongside the Americans and became a close ally of Washington?`, ch:[`Napoleon Bonaparte`,`Marquis de Lafayette`,`Charles de Gaulle`,`Louis XVI`], ans:1, exp:`The Marquis de Lafayette was a young French aristocrat who fought for the American cause and became a trusted officer under Washington.` },
    ]
  },
  { id:'hs05', cat:'Behavioral & Social Sciences', title:`The Civil War Era`, diff:'Medium', qs:[
      { q:`What was the central, underlying cause of the US Civil War?`, ch:[`Disagreement over tariffs on European goods`,`Slavery and its expansion into new territories`,`A dispute over the national capital's location`,`Conflict over immigration policy`], ans:1, exp:`Slavery, and especially whether it would expand into new western territories, was the central cause of the Civil War.` },
      { q:`The Missouri Compromise of 1820 attempted to balance the number of slave and free states by:`, ch:[`Admitting Missouri as a slave state and Maine as a free state`,`Banning slavery everywhere in the country`,`Making all new states free`,`Giving each state a popular vote on statehood`], ans:0, exp:`The Missouri Compromise admitted Missouri as a slave state and Maine as a free state, and drew a line limiting slavery's expansion.` },
      { q:`The Kansas-Nebraska Act of 1854 allowed the residents of those territories to:`, ch:[`Vote directly for president`,`Decide for themselves whether to allow slavery (popular sovereignty)`,`Secede from the Union`,`Elect their own Supreme Court`], ans:1, exp:`The Kansas-Nebraska Act let settlers decide the slavery question by popular sovereignty, leading to violent conflict known as "Bleeding Kansas."` },
      { q:`In the Dred Scott decision of 1857, the Supreme Court ruled that:`, ch:[`Enslaved people were not citizens and had no right to sue in federal court`,`Slavery was unconstitutional in all states`,`All enslaved people would be freed immediately`,`States could not regulate slavery at all`], ans:0, exp:`The Supreme Court ruled that Dred Scott, an enslaved man, was not a citizen and had no standing to sue for his freedom.` },
      { q:`Which state was the first to secede from the Union after Lincoln's election in 1860?`, ch:[`Georgia`,`Texas`,`South Carolina`,`Virginia`], ans:2, exp:`South Carolina became the first state to secede from the Union in December 1860, shortly after Lincoln's election.` },
      { q:`Who served as president of the Confederate States of America?`, ch:[`Robert E. Lee`,`Jefferson Davis`,`Stephen Douglas`,`Alexander Stephens`], ans:1, exp:`Jefferson Davis was chosen as the president of the Confederacy when it formed in 1861.` },
      { q:`The Civil War began in April 1861 with an attack on which federal fort?`, ch:[`Fort Sumter`,`Fort McHenry`,`Fort Knox`,`Fort Ticonderoga`], ans:0, exp:`Confederate forces fired on Fort Sumter in South Carolina in April 1861, marking the start of the Civil War.` },
      { q:`The Emancipation Proclamation, issued in 1863, declared that:`, ch:[`Slavery was abolished nationwide immediately`,`Enslaved people in Confederate-held territory were declared free`,`The Confederacy had surrendered`,`Women gained the right to vote`], ans:1, exp:`Lincoln's Emancipation Proclamation declared enslaved people in Confederate states free, though slavery wasn't fully abolished nationwide until the 13th Amendment.` },
      { q:`The 1863 battle often considered the turning point of the Civil War, fought in Pennsylvania, was:`, ch:[`The Battle of Bull Run`,`The Battle of Antietam`,`The Battle of Gettysburg`,`The Battle of Shiloh`], ans:2, exp:`The Battle of Gettysburg in July 1863 was a major Union victory and is widely seen as the turning point of the war.` },
      { q:`Which Union general accepted General Robert E. Lee's surrender in 1865?`, ch:[`William Tecumseh Sherman`,`George McClellan`,`Ulysses S. Grant`,`Ambrose Burnside`], ans:2, exp:`Ulysses S. Grant accepted Lee's surrender at Appomattox Court House, Virginia, in April 1865, effectively ending the war.` },
      { q:`Which amendment officially abolished slavery throughout the United States?`, ch:[`12th Amendment`,`13th Amendment`,`14th Amendment`,`15th Amendment`], ans:1, exp:`The 13th Amendment, ratified in December 1865, formally abolished slavery nationwide.` },
      { q:`At the start of the Civil War, states that seceded from the Union were known collectively as the:`, ch:[`Union`,`Confederacy`,`Dominion`,`Territories`], ans:1, exp:`The eleven Southern states that seceded formed the Confederate States of America, commonly called the Confederacy.` },
    ]
  },
  { id:'hs06', cat:'Behavioral & Social Sciences', title:`The Industrial Revolution`, diff:'Medium', qs:[
      { q:`The Industrial Revolution first began in which country in the late 1700s?`, ch:[`United States`,`Germany`,`Great Britain`,`France`], ans:2, exp:`The Industrial Revolution began in Great Britain in the late 18th century before spreading to other countries.` },
      { q:`Which invention, improved by James Watt, became a key power source for factories and transportation?`, ch:[`The steam engine`,`The telegraph`,`The light bulb`,`The internal combustion engine`], ans:0, exp:`James Watt's improvements to the steam engine made it efficient enough to power factories, trains, and ships.` },
      { q:`Early textile industry innovations, such as the spinning jenny, mainly improved the production of:`, ch:[`Steel`,`Cloth and thread`,`Automobiles`,`Electricity`], ans:1, exp:`Machines like the spinning jenny sped up the spinning of thread, transforming textile (cloth) production.` },
      { q:`The factory system marked a shift in production because work moved from:`, ch:[`Large corporations to small family shops`,`Individual homes to centralized factories`,`Rural farms to fishing villages`,`Cities to rural areas`], ans:1, exp:`Under the factory system, goods once made by hand at home were increasingly produced in centralized factories using machines.` },
      { q:`The rapid growth of cities during the Industrial Revolution, as people moved for factory jobs, is called:`, ch:[`Urbanization`,`Colonization`,`Globalization`,`Federalism`], ans:0, exp:`Urbanization describes the growth of city populations, largely driven by people seeking factory work.` },
      { q:`Which transportation innovation, powered by the steam engine, dramatically sped up the movement of goods and people?`, ch:[`The automobile`,`The airplane`,`The railroad`,`The subway`], ans:2, exp:`Steam-powered railroads allowed goods and people to travel much faster and farther than before, boosting trade and industry.` },
      { q:`The Bessemer process was an important innovation for mass-producing:`, ch:[`Cotton`,`Steel`,`Coal`,`Electricity`], ans:1, exp:`The Bessemer process made it possible to produce steel quickly and cheaply, fueling railroad and building construction.` },
      { q:`Henry Ford is best known for pioneering which manufacturing method in the United States?`, ch:[`Handcrafted, custom-built products`,`The moving assembly line for mass production`,`Government-owned factories`,`Cottage industry weaving`], ans:1, exp:`Henry Ford's moving assembly line dramatically sped up automobile production, most famously with the Model T.` },
      { q:`Poor factory conditions, including long hours and child labor, eventually led workers to:`, ch:[`Move back to farming full time`,`Form labor unions to demand better conditions`,`Stop using machines entirely`,`Ask the king to abolish factories`], ans:1, exp:`Workers organized labor unions to collectively bargain for better wages, hours, and safer working conditions.` },
      { q:`Adam Smith, author of "The Wealth of Nations," is closely associated with the idea of:`, ch:[`Central government control of all industries`,`Free markets guided by supply and demand`,`Abolishing private property`,`State-run collective farms`], ans:1, exp:`Adam Smith argued that free markets, driven by competition and self-interest, efficiently allocate resources without heavy government control.` },
      { q:`Which of these was a major innovation of the "Second" Industrial Revolution in the late 1800s?`, ch:[`Electricity and the telegraph`,`The printing press`,`Gunpowder`,`The wheel`], ans:0, exp:`The Second Industrial Revolution brought innovations like electricity and the telegraph, further transforming industry and communication.` },
      { q:`Overall, the Industrial Revolution shifted many economies from being mainly:`, ch:[`Agricultural to industrial`,`Industrial to agricultural`,`Digital to industrial`,`Service-based to agricultural`], ans:0, exp:`Economies shifted from being centered on farming (agrarian) to being centered on factory-based manufacturing (industrial).` },
    ]
  },
  { id:'hs07', cat:'Behavioral & Social Sciences', title:`World War I Basics`, diff:'Medium', qs:[
      { q:`In what years was World War I fought?`, ch:[`1905-1910`,`1914-1918`,`1920-1924`,`1939-1945`], ans:1, exp:`World War I lasted from 1914 to 1918.` },
      { q:`Which event is generally considered the immediate trigger for World War I?`, ch:[`The invasion of Poland`,`The assassination of Archduke Franz Ferdinand`,`The sinking of the Lusitania`,`The bombing of Pearl Harbor`], ans:1, exp:`The assassination of Archduke Franz Ferdinand of Austria-Hungary in Sarajevo in June 1914 set off a chain of events leading to war.` },
      { q:`The two main opposing alliances in World War I were the Allied Powers and the:`, ch:[`Axis Powers`,`Central Powers`,`Warsaw Pact`,`Coalition Powers`], ans:1, exp:`World War I was fought between the Allied Powers and the Central Powers.` },
      { q:`Which countries made up the core of the Central Powers?`, ch:[`Britain, France, and Russia`,`Germany, Austria-Hungary, and the Ottoman Empire`,`United States, Italy, and Japan`,`Spain, Portugal, and Belgium`], ans:1, exp:`The Central Powers were led by Germany and Austria-Hungary, later joined by the Ottoman Empire and Bulgaria.` },
      { q:`Which of these countries fought as part of the Allied Powers?`, ch:[`Germany`,`Austria-Hungary`,`France`,`The Ottoman Empire`], ans:2, exp:`France, along with Britain and Russia, was one of the main Allied Powers, later joined by the United States.` },
      { q:`Much of the fighting on the Western Front was characterized by:`, ch:[`Naval blockades only`,`Trench warfare with little territorial change`,`Fast-moving tank battles across open desert`,`Guerrilla warfare in jungles`], ans:1, exp:`Soldiers on the Western Front dug extensive trench systems, leading to brutal, slow-moving warfare with heavy casualties.` },
      { q:`Which of these weapons was newly introduced or first widely used during World War I?`, ch:[`Muskets`,`Poison gas`,`Longbows`,`Nuclear bombs`], ans:1, exp:`Poison gas was introduced as a weapon during World War I, along with machine guns and early tanks.` },
      { q:`A major factor that led the United States to enter World War I in 1917 was:`, ch:[`The attack on Pearl Harbor`,`German unrestricted submarine warfare and the Zimmermann Telegram`,`The assassination of a US president`,`An invasion of American territory`], ans:1, exp:`German attacks on ships and the Zimmermann Telegram, which proposed a German-Mexican alliance against the US, pushed America to join the war.` },
      { q:`Which treaty officially ended World War I in 1919?`, ch:[`Treaty of Paris`,`Treaty of Versailles`,`Treaty of Ghent`,`Treaty of Tordesillas`], ans:1, exp:`The Treaty of Versailles, signed in 1919, formally ended World War I and imposed harsh terms on Germany.` },
      { q:`Under the Treaty of Versailles, Germany was primarily required to:`, ch:[`Take no responsibility and pay nothing`,`Accept blame for the war and pay reparations`,`Join the Allied Powers`,`Gain new colonies`], ans:1, exp:`The Treaty of Versailles forced Germany to accept blame for the war and pay heavy financial reparations.` },
      { q:`US President Woodrow Wilson proposed a peace plan known as the:`, ch:[`New Deal`,`Fourteen Points`,`Marshall Plan`,`Monroe Doctrine`], ans:1, exp:`Wilson's Fourteen Points outlined his vision for a lasting peace, including the creation of an international peacekeeping organization.` },
      { q:`The international organization created after World War I to help prevent future wars was the:`, ch:[`United Nations`,`League of Nations`,`European Union`,`World Trade Organization`], ans:1, exp:`The League of Nations was formed after World War I to encourage cooperation between countries and prevent future conflicts.` },
    ]
  },
  { id:'hs08', cat:'Behavioral & Social Sciences', title:`World War II Basics`, diff:'Medium', qs:[
      { q:`World War II in Europe began in 1939 when Germany invaded:`, ch:[`France`,`Poland`,`The Soviet Union`,`Britain`], ans:1, exp:`Germany's invasion of Poland in September 1939 prompted Britain and France to declare war, starting World War II in Europe.` },
      { q:`Which three countries made up the main Axis Powers?`, ch:[`Germany, Italy, and Japan`,`Britain, France, and the Soviet Union`,`Germany, Britain, and the United States`,`Italy, Spain, and Portugal`], ans:0, exp:`The Axis Powers were led by Nazi Germany, Fascist Italy, and Imperial Japan.` },
      { q:`Which of the following was one of the main Allied Powers in World War II?`, ch:[`Germany`,`Japan`,`The Soviet Union`,`Italy`], ans:2, exp:`The main Allied Powers included the United States, Britain, the Soviet Union, France, and China.` },
      { q:`The attack that brought the United States directly into World War II was on:`, ch:[`Pearl Harbor`,`Normandy`,`Midway Island`,`The Panama Canal`], ans:0, exp:`Japan's surprise attack on Pearl Harbor, Hawaii, on December 7, 1941, led the US to declare war.` },
      { q:`D-Day, on June 6, 1944, refers to:`, ch:[`The bombing of Hiroshima`,`The Allied invasion of Normandy, France`,`Germany's surrender`,`The start of the Battle of Britain`], ans:1, exp:`D-Day was the massive Allied invasion of Normandy, France, opening a major front against Germany in Western Europe.` },
      { q:`The Holocaust refers to:`, ch:[`A major naval battle in the Pacific`,`The Nazi genocide of six million Jews and other targeted groups`,`The bombing campaign over London`,`Japan's occupation of China`], ans:1, exp:`The Holocaust was the systematic, state-sponsored murder of six million Jews and millions of others by Nazi Germany.` },
      { q:`Who was the leader of Nazi Germany during World War II?`, ch:[`Benito Mussolini`,`Adolf Hitler`,`Joseph Stalin`,`Hideki Tojo`], ans:1, exp:`Adolf Hitler led Nazi Germany and was the driving force behind its aggression and the Holocaust.` },
      { q:`The war in Europe ended in May 1945 on a date commonly known as:`, ch:[`D-Day`,`V-E Day`,`V-J Day`,`Armistice Day`], ans:1, exp:`V-E Day (Victory in Europe Day) marked Germany's surrender in May 1945.` },
      { q:`The war in the Pacific ended in August 1945 after the United States:`, ch:[`Signed a non-aggression pact with Japan`,`Dropped atomic bombs on Hiroshima and Nagasaki`,`Invaded mainland Japan by land`,`Blockaded China`], ans:1, exp:`The atomic bombings of Hiroshima and Nagasaki led Japan to surrender, ending World War II in August 1945.` },
      { q:`At the Yalta Conference in 1945, which three Allied leaders met to plan the postwar world?`, ch:[`Roosevelt, Churchill, and Stalin`,`Truman, De Gaulle, and Hirohito`,`Roosevelt, Hitler, and Churchill`,`Churchill, Mussolini, and Stalin`], ans:0, exp:`US President Roosevelt, British Prime Minister Churchill, and Soviet leader Stalin met at Yalta to discuss the postwar order.` },
      { q:`The international organization founded in 1945, after World War II, to promote peace and cooperation among nations is the:`, ch:[`League of Nations`,`United Nations`,`NATO`,`European Union`], ans:1, exp:`The United Nations was established in 1945 to help maintain international peace and security after World War II.` },
      { q:`Approximately when did World War II take place?`, ch:[`1914-1918`,`1929-1933`,`1939-1945`,`1950-1953`], ans:2, exp:`World War II lasted from 1939, when Germany invaded Poland, to 1945, when Japan surrendered.` },
    ]
  },
  { id:'hs09', cat:'Behavioral & Social Sciences', title:`The Cold War Basics`, diff:'Medium', qs:[
      { q:`The Cold War was best described as a period of tension mainly between which two powers?`, ch:[`The United States and Japan`,`The United States and the Soviet Union`,`Britain and France`,`Germany and Russia`], ans:1, exp:`The Cold War was a decades-long standoff of political and military tension between the United States and the Soviet Union, without direct large-scale war between them.` },
      { q:`The term "Iron Curtain" referred to:`, ch:[`A physical wall around Moscow`,`The divide between communist Eastern Europe and the democratic West`,`A trade barrier between the US and Japan`,`A weapons treaty between NATO nations`], ans:1, exp:`"Iron Curtain," popularized by Winston Churchill, described the political and ideological divide separating Soviet-controlled Eastern Europe from the West.` },
      { q:`The Berlin Wall, built in 1961, divided:`, ch:[`East and West Berlin`,`North and South Korea`,`East and West Germany's capitals only`,`Paris and Berlin`], ans:0, exp:`The Berlin Wall separated communist East Berlin from democratic West Berlin until it fell in 1989.` },
      { q:`The Marshall Plan was a US program designed to:`, ch:[`Provide economic aid to help rebuild Western Europe after World War II`,`Fund the space race`,`Support communist governments in Asia`,`Build the interstate highway system`], ans:0, exp:`The Marshall Plan provided billions of dollars in US aid to help rebuild Western European economies after World War II.` },
      { q:`NATO, formed in 1949, was a military alliance made up of:`, ch:[`The Soviet Union and its satellite states`,`The United States, Canada, and Western European allies`,`Only Asian nations`,`The United Nations Security Council members`], ans:1, exp:`NATO (North Atlantic Treaty Organization) linked the US, Canada, and Western European nations in a mutual defense alliance against Soviet expansion.` },
      { q:`The Warsaw Pact was:`, ch:[`A Soviet-led military alliance of Eastern Bloc countries`,`A trade agreement between the US and Europe`,`A treaty ending the Korean War`,`An agreement to ban nuclear weapons`], ans:0, exp:`The Warsaw Pact was the Soviet Union's answer to NATO, uniting the USSR with communist Eastern European states militarily.` },
      { q:`The Cuban Missile Crisis of 1962 was a tense standoff over:`, ch:[`Cuban control of the Panama Canal`,`Soviet nuclear missiles placed in Cuba`,`A US invasion of Cuba`,`Cuban membership in NATO`], ans:1, exp:`The crisis erupted when the US discovered Soviet nuclear missiles in Cuba, bringing the two superpowers close to war before a diplomatic resolution.` },
      { q:`The Korean War (1950-1953) was fought between:`, ch:[`North Korea (communist) and South Korea, backed by the US and UN forces`,`China and Japan`,`The Soviet Union and Japan`,`North and South Vietnam`], ans:0, exp:`The Korean War pitted communist North Korea, backed by China and the Soviet Union, against South Korea, defended by the US and United Nations forces.` },
      { q:`The Vietnam War involved the United States supporting:`, ch:[`Communist North Vietnam`,`South Vietnam against the communist North`,`France's colonial rule`,`China against Vietnam`], ans:1, exp:`The US supported South Vietnam in its conflict against the communist North Vietnamese government and its allies.` },
      { q:`Which event marked the Soviet Union's early lead in the "Space Race"?`, ch:[`The Apollo 11 moon landing`,`The launch of Sputnik in 1957`,`The founding of NASA`,`The Cuban Missile Crisis`], ans:1, exp:`The Soviet Union launched Sputnik, the first artificial satellite, in 1957, spurring the US to accelerate its own space program.` },
      { q:`The Cold War effectively came to an end around:`, ch:[`1945, with the end of World War II`,`1991, with the collapse of the Soviet Union`,`1963, with the Cuban Missile Crisis`,`1975, with the end of the Vietnam War`], ans:1, exp:`The Cold War is generally considered to have ended in 1991 when the Soviet Union dissolved.` },
      { q:`The US policy of trying to stop the spread of communism to new countries was known as:`, ch:[`Containment`,`Isolationism`,`Appeasement`,`Détente only`], ans:0, exp:`Containment was the US strategy aimed at preventing communism from spreading beyond where it already existed.` },
    ]
  },
  { id:'hs10', cat:'Behavioral & Social Sciences', title:`The Civil Rights Movement`, diff:'Medium', qs:[
      { q:`The 1954 Supreme Court case that declared racial segregation in public schools unconstitutional was:`, ch:[`Plessy v. Ferguson`,`Brown v. Board of Education`,`Roe v. Wade`,`Marbury v. Madison`], ans:1, exp:`Brown v. Board of Education (1954) ruled that "separate but equal" public schools were unconstitutional, overturning earlier segregation precedent.` },
      { q:`Rosa Parks became a key figure in the Civil Rights Movement in 1955 by:`, ch:[`Organizing the March on Washington`,`Refusing to give up her bus seat to a white passenger in Montgomery`,`Filing the Brown v. Board lawsuit`,`Leading the Freedom Riders`], ans:1, exp:`Rosa Parks's refusal to give up her seat on a Montgomery, Alabama bus sparked the Montgomery Bus Boycott.` },
      { q:`The Montgomery Bus Boycott was primarily led by:`, ch:[`Malcolm X`,`Martin Luther King Jr.`,`Thurgood Marshall`,`John F. Kennedy`], ans:1, exp:`Martin Luther King Jr. rose to national prominence as a leader of the Montgomery Bus Boycott in 1955-56.` },
      { q:`Martin Luther King Jr. delivered his famous "I Have a Dream" speech in 1963 at the:`, ch:[`Lincoln Memorial during the March on Washington`,`United Nations`,`US Capitol`,`Alabama State Capitol`], ans:0, exp:`King delivered the speech from the steps of the Lincoln Memorial during the March on Washington for Jobs and Freedom.` },
      { q:`The Civil Rights Act of 1964 primarily:`, ch:[`Ended slavery`,`Outlawed discrimination based on race, color, religion, sex, and national origin`,`Gave women the right to vote`,`Established Social Security`], ans:1, exp:`The Civil Rights Act of 1964 banned discrimination in public places, employment, and other areas based on race, color, religion, sex, and national origin.` },
      { q:`The Voting Rights Act of 1965 aimed to:`, ch:[`Lower the voting age to 18`,`Eliminate discriminatory voting practices such as literacy tests`,`Create the Electoral College`,`End the poll tax in state elections`], ans:1, exp:`The Voting Rights Act banned discriminatory practices like literacy tests that had been used to prevent Black Americans from voting.` },
      { q:`The "Little Rock Nine" in 1957 were known for:`, ch:[`Organizing the first Freedom Ride`,`Being the first Black students to integrate Little Rock Central High School`,`Founding the NAACP`,`Leading the Montgomery Bus Boycott`], ans:1, exp:`The Little Rock Nine were Black students who integrated Central High School in Arkansas in 1957, facing intense resistance.` },
      { q:`Malcolm X is best known as a civil rights leader who:`, ch:[`Advocated strictly for nonviolent protest`,`Promoted Black empowerment and self-defense`,`Led the Montgomery Bus Boycott`,`Wrote the Civil Rights Act`], ans:1, exp:`Malcolm X advocated for Black pride, self-reliance, and self-defense, offering a different approach from the nonviolent strategy of Martin Luther King Jr.` },
      { q:`The Freedom Riders of 1961 worked to challenge segregation by:`, ch:[`Riding interstate buses into the segregated South`,`Boycotting northern businesses`,`Running for Congress`,`Organizing a national school boycott`], ans:0, exp:`Freedom Riders rode interstate buses into the South to test and challenge laws that kept bus terminals segregated.` },
      { q:`Martin Luther King Jr. was assassinated in 1968 in which city?`, ch:[`Atlanta`,`Memphis`,`Selma`,`Birmingham`], ans:1, exp:`Martin Luther King Jr. was assassinated in Memphis, Tennessee, in April 1968.` },
      { q:`Martin Luther King Jr.'s strategy of nonviolent civil disobedience was inspired in part by:`, ch:[`Mahatma Gandhi`,`Winston Churchill`,`Vladimir Lenin`,`Theodore Roosevelt`], ans:0, exp:`King drew significant inspiration from Mahatma Gandhi's philosophy of nonviolent resistance used in India's independence movement.` },
      { q:`The 24th Amendment, ratified in 1964, banned the use of:`, ch:[`Literacy tests in federal elections`,`Poll taxes in federal elections`,`The Electoral College`,`At-large voting districts`], ans:1, exp:`The 24th Amendment eliminated poll taxes as a requirement for voting in federal elections, removing a barrier that had disproportionately affected poorer and Black voters.` },
    ]
  },
  { id:'hs11', cat:'Behavioral & Social Sciences', title:`Ancient Civilizations Basics (Egypt, Greece, Rome)`, diff:'Easy', qs:[
      { q:`Ancient Egyptian civilization developed along which river?`, ch:[`The Tigris`,`The Nile`,`The Amazon`,`The Euphrates`], ans:1, exp:`Ancient Egypt grew along the Nile River, which provided water and fertile soil for farming in the surrounding desert.` },
      { q:`What was the title given to the rulers of ancient Egypt?`, ch:[`Pharaoh`,`Caesar`,`Emperor`,`Consul`], ans:0, exp:`Ancient Egyptian rulers were called pharaohs and were often viewed as divine or semi-divine figures.` },
      { q:`The Great Pyramids of ancient Egypt were primarily built to serve as:`, ch:[`Marketplaces`,`Tombs for pharaohs`,`Military forts`,`Temples for foreign gods`], ans:1, exp:`The pyramids were monumental tombs built to house and protect the bodies and belongings of Egyptian pharaohs.` },
      { q:`The ancient Egyptian writing system, using pictures and symbols, is known as:`, ch:[`Cuneiform`,`Hieroglyphics`,`Sanskrit`,`Latin script`], ans:1, exp:`Hieroglyphics used pictures and symbols to represent words and sounds in ancient Egyptian writing.` },
      { q:`Which ancient Greek city-state is often called the birthplace of democracy?`, ch:[`Sparta`,`Corinth`,`Athens`,`Thebes`], ans:2, exp:`Athens developed an early form of democracy in which citizens could vote directly on laws and policies.` },
      { q:`Which ancient Greek city-state was best known for its powerful, disciplined military?`, ch:[`Athens`,`Sparta`,`Delphi`,`Crete`], ans:1, exp:`Sparta was famous for its rigorous military training and society organized around producing strong soldiers.` },
      { q:`Which three philosophers, teacher and student of one another, are central to ancient Greek philosophy?`, ch:[`Homer, Herodotus, and Sophocles`,`Socrates, Plato, and Aristotle`,`Alexander, Pericles, and Solon`,`Zeus, Apollo, and Athena`], ans:1, exp:`Socrates taught Plato, who in turn taught Aristotle — together they laid much of the foundation of Western philosophy.` },
      { q:`Before becoming an empire, ancient Rome was governed as a:`, ch:[`Monarchy only`,`Republic`,`Theocracy`,`Direct democracy`], ans:1, exp:`Rome was governed as a republic, with elected officials and a Senate, before transitioning to rule by emperors.` },
      { q:`Who is considered the first emperor of Rome?`, ch:[`Julius Caesar`,`Nero`,`Augustus`,`Constantine`], ans:2, exp:`Augustus became Rome's first emperor after the fall of the Republic, beginning the era of the Roman Empire.` },
      { q:`Which of these is a well-known achievement of ancient Roman engineering?`, ch:[`The pyramids`,`Aqueducts and an extensive road network`,`The Parthenon`,`Hieroglyphic writing`], ans:1, exp:`The Romans built extensive roads and aqueducts that carried water long distances, showcasing advanced engineering skills.` },
      { q:`The Western Roman Empire is traditionally said to have fallen in what year?`, ch:[`27 BCE`,`476 CE`,`800 CE`,`1000 CE`], ans:1, exp:`The Western Roman Empire is traditionally considered to have fallen in 476 CE, when the last Roman emperor was deposed.` },
      { q:`The tradition of the Olympic Games originated in:`, ch:[`Ancient Rome`,`Ancient Egypt`,`Ancient Greece`,`Ancient China`], ans:2, exp:`The Olympic Games began in ancient Greece as athletic competitions held in honor of the god Zeus.` },
    ]
  },
  { id:'hs12', cat:'Behavioral & Social Sciences', title:`World Geography Basics`, diff:'Easy', qs:[
      { q:`Which is the largest continent by land area?`, ch:[`Africa`,`Asia`,`North America`,`Europe`], ans:1, exp:`Asia is the largest continent by both land area and population.` },
      { q:`Which is the largest ocean on Earth?`, ch:[`Atlantic Ocean`,`Indian Ocean`,`Arctic Ocean`,`Pacific Ocean`], ans:3, exp:`The Pacific Ocean is the largest and deepest of Earth's oceans.` },
      { q:`Which river is traditionally considered the longest in the world?`, ch:[`The Amazon`,`The Nile`,`The Mississippi`,`The Yangtze`], ans:1, exp:`The Nile River, flowing through northeastern Africa, is traditionally cited as the longest river in the world.` },
      { q:`Which is the largest hot desert in the world?`, ch:[`The Gobi Desert`,`The Sahara Desert`,`The Mojave Desert`,`The Kalahari Desert`], ans:1, exp:`The Sahara, located in North Africa, is the largest hot desert in the world.` },
      { q:`Mount Everest, the tallest mountain above sea level, is located in which mountain range?`, ch:[`The Andes`,`The Rockies`,`The Alps`,`The Himalayas`], ans:3, exp:`Mount Everest sits in the Himalayas on the border of Nepal and Tibet (China), and is the highest peak above sea level.` },
      { q:`Ancient Egypt is located on which continent?`, ch:[`Asia`,`Africa`,`Europe`,`South America`], ans:1, exp:`Egypt is located in northeastern Africa.` },
      { q:`The equator divides the Earth into which two regions?`, ch:[`Eastern and Western Hemispheres`,`Northern and Southern Hemispheres`,`Land and water regions`,`Tropical and Arctic zones`], ans:1, exp:`The equator is an imaginary line around the Earth's middle that divides it into the Northern and Southern Hemispheres.` },
      { q:`How many continents are typically recognized in the commonly taught model?`, ch:[`Five`,`Six`,`Seven`,`Eight`], ans:2, exp:`The commonly taught model recognizes seven continents: Africa, Antarctica, Asia, Australia/Oceania, Europe, North America, and South America.` },
      { q:`Which country has the largest total land area in the world?`, ch:[`China`,`Canada`,`Russia`,`United States`], ans:2, exp:`Russia is the largest country in the world by land area, spanning parts of both Europe and Asia.` },
      { q:`The Amazon Rainforest is located primarily within which country?`, ch:[`Peru`,`Colombia`,`Brazil`,`Venezuela`], ans:2, exp:`The majority of the Amazon Rainforest lies within Brazil, though it extends into several other South American countries.` },
      { q:`The Great Barrier Reef, the world's largest coral reef system, lies off the coast of:`, ch:[`Indonesia`,`Australia`,`The Philippines`,`South Africa`], ans:1, exp:`The Great Barrier Reef stretches along the northeastern coast of Australia.` },
      { q:`Which mountain range is traditionally used as the geographic boundary between Europe and Asia?`, ch:[`The Alps`,`The Himalayas`,`The Ural Mountains`,`The Atlas Mountains`], ans:2, exp:`The Ural Mountains in Russia are commonly used as the dividing line between the continents of Europe and Asia.` },
    ]
  },
  { id:'hs13', cat:'Behavioral & Social Sciences', title:`Economics Basics: Supply & Demand`, diff:'Easy', qs:[
      { q:`According to the law of demand, as the price of a good increases, the quantity demanded generally:`, ch:[`Increases`,`Decreases`,`Stays the same`,`Becomes unpredictable`], ans:1, exp:`The law of demand states that, all else equal, higher prices lead consumers to buy less of a good.` },
      { q:`According to the law of supply, as the price of a good increases, the quantity supplied generally:`, ch:[`Decreases`,`Stays the same`,`Increases`,`Drops to zero`], ans:2, exp:`The law of supply states that producers are generally willing to supply more of a good as its price rises.` },
      { q:`The price at which the quantity supplied equals the quantity demanded is called the:`, ch:[`Inflation rate`,`Equilibrium price`,`Minimum wage`,`Opportunity cost`], ans:1, exp:`The equilibrium price is where the supply and demand curves intersect, balancing quantity supplied and quantity demanded.` },
      { q:`A market surplus occurs when, at a given price:`, ch:[`Quantity demanded exceeds quantity supplied`,`Quantity supplied exceeds quantity demanded`,`Supply and demand are exactly equal`,`Prices are set by the government`], ans:1, exp:`A surplus happens when producers supply more of a good than consumers are willing to buy at that price.` },
      { q:`A market shortage occurs when, at a given price:`, ch:[`Quantity supplied exceeds quantity demanded`,`Prices are too high for anyone to buy`,`Quantity demanded exceeds quantity supplied`,`There is no demand at all`], ans:2, exp:`A shortage happens when consumers want to buy more of a good than producers are currently supplying at that price.` },
      { q:`Scarcity, a foundational concept in economics, refers to:`, ch:[`The idea that resources are unlimited`,`The gap between unlimited human wants and limited available resources`,`Government control of prices`,`A sudden drop in demand`], ans:1, exp:`Scarcity is the basic economic problem that resources are limited while human wants and needs are essentially unlimited.` },
      { q:`Opportunity cost refers to:`, ch:[`The total cost of producing a good`,`The value of the next best alternative given up when making a choice`,`The tax added to a purchase`,`The price set by the government`], ans:1, exp:`Opportunity cost is what you give up (the next best alternative) when you choose one option over another.` },
      { q:`On a standard supply-and-demand graph, the supply curve is typically drawn:`, ch:[`Sloping upward from left to right`,`Sloping downward from left to right`,`As a flat horizontal line`,`As a flat vertical line`], ans:0, exp:`The supply curve usually slopes upward, showing that producers supply more as price rises.` },
      { q:`On a standard supply-and-demand graph, the demand curve is typically drawn:`, ch:[`Sloping upward from left to right`,`Sloping downward from left to right`,`As a flat horizontal line`,`As a flat vertical line`], ans:1, exp:`The demand curve usually slopes downward, showing that consumers buy less as price rises.` },
      { q:`A free market economic system is one in which prices are mainly determined by:`, ch:[`Government-set price controls`,`Supply and demand with limited government intervention`,`A single company that sets all prices`,`Random assignment each year`], ans:1, exp:`In a free market, prices emerge from the interaction of supply and demand rather than being directly set by the government.` },
      { q:`A general, sustained rise in the prices of goods and services over time is called:`, ch:[`Deflation`,`Inflation`,`Recession`,`Equilibrium`], ans:1, exp:`Inflation describes a broad, ongoing increase in prices, which reduces the purchasing power of money over time.` },
      { q:`Which of these would most directly cause the demand curve for a good to shift, rather than just causing movement along it?`, ch:[`A change in the good's own price`,`A change in consumer income or preferences`,`A change in the units used to measure price`,`Rounding the price to the nearest dollar`], ans:1, exp:`Changes in consumer income, preferences, or the price of related goods shift the whole demand curve, while a change in the good's own price causes movement along the existing curve.` },
    ]
  },
  { id:'hs14', cat:'Behavioral & Social Sciences', title:`Elections & Voting in the US`, diff:'Easy', qs:[
      { q:`What is the minimum voting age in United States federal elections?`, ch:[`16`,`18`,`21`,`25`], ans:1, exp:`The 26th Amendment set the minimum voting age at 18 for all US elections.` },
      { q:`US presidential elections are held every:`, ch:[`2 years`,`4 years`,`6 years`,`8 years`], ans:1, exp:`Presidential elections occur every four years, always in November.` },
      { q:`The system used to formally elect the US President, rather than a direct nationwide popular vote, is called the:`, ch:[`Congressional Caucus`,`Electoral College`,`Popular Assembly`,`National Convention`], ans:1, exp:`The President is formally elected by the Electoral College, a body of electors allocated to each state.` },
      { q:`How many electoral votes does a candidate need to win the presidency?`, ch:[`218`,`270`,`300`,`435`], ans:1, exp:`A candidate needs a majority of the 538 electoral votes, which is 270, to win the presidency.` },
      { q:`The main purpose of a primary election is to:`, ch:[`Choose a party's nominee for the general election`,`Elect the President directly`,`Redraw congressional districts`,`Approve constitutional amendments`], ans:0, exp:`Primary elections let party voters choose which candidate will represent their party in the general election.` },
      { q:`Midterm elections take place:`, ch:[`On the same day as the presidential election`,`Halfway through a president's four-year term`,`Every ten years`,`Only in leap years divisible by four`], ans:1, exp:`Midterm elections occur two years into a president's term and determine many seats in Congress.` },
      { q:`The practice of drawing voting district boundaries to favor a particular political party is known as:`, ch:[`Redistricting only`,`Gerrymandering`,`Filibustering`,`Canvassing`], ans:1, exp:`Gerrymandering refers to manipulating district lines to give one party or group an electoral advantage.` },
      { q:`Before voting in most US elections, a citizen must first:`, ch:[`Take a civics exam`,`Register to vote`,`Join a political party`,`Pay a fee`], ans:1, exp:`Most states require citizens to register to vote before they can cast a ballot in an election.` },
      { q:`A voting system in which a person's ballot choice is kept private is called a:`, ch:[`Public ballot`,`Secret ballot`,`Open primary`,`Straw poll`], ans:1, exp:`The secret ballot allows voters to cast their votes privately, without revealing their choices to others.` },
      { q:`How long is a term for a US Senator?`, ch:[`2 years`,`4 years`,`6 years`,`8 years`], ans:2, exp:`US Senators serve six-year terms, with about one-third of the Senate up for election every two years.` },
      { q:`How long is a term for a member of the US House of Representatives?`, ch:[`2 years`,`4 years`,`6 years`,`8 years`], ans:0, exp:`Members of the House of Representatives serve two-year terms, meaning the entire House is up for election every election cycle.` },
      { q:`In most US states, how are a state's electoral votes typically awarded?`, ch:[`Split proportionally to match the statewide popular vote`,`On a winner-take-all basis to whoever wins the statewide popular vote`,`Chosen randomly by lottery`,`Decided by the state legislature after the election`], ans:1, exp:`Most states award all of their electoral votes to whichever candidate wins that state's popular vote, though Maine and Nebraska use a different method.` },
    ]
  },
  { id:'hs15', cat:'Behavioral & Social Sciences', title:`Global Cultures & World Religions Basics`, diff:'Easy', qs:[
      { q:`Christianity is centered on the life and teachings of:`, ch:[`Muhammad`,`Jesus Christ`,`Siddhartha Gautama`,`Confucius`], ans:1, exp:`Christianity is based on the life and teachings of Jesus Christ, and its central religious text is the Bible.` },
      { q:`Islam is based on the teachings of the Prophet Muhammad and its holy book is the:`, ch:[`Torah`,`Bible`,`Quran`,`Vedas`], ans:2, exp:`Muslims follow the teachings of the Prophet Muhammad as recorded in the Quran, Islam's central religious text.` },
      { q:`Judaism, one of the world's oldest monotheistic religions, considers which text central to its faith?`, ch:[`The Torah`,`The Quran`,`The Bhagavad Gita`,`The Analects`], ans:0, exp:`The Torah is the central text of Judaism, containing its core teachings and laws.` },
      { q:`Hinduism, practiced by a large majority of people in India, includes core concepts such as:`, ch:[`Karma and dharma`,`Original sin`,`The Five Pillars`,`The Ten Commandments`], ans:0, exp:`Hinduism includes core concepts like karma (the consequences of one's actions) and dharma (one's duty or righteous path in life).` },
      { q:`Buddhism was founded by which historical figure?`, ch:[`Confucius`,`Siddhartha Gautama (the Buddha)`,`Muhammad`,`Moses`], ans:1, exp:`Buddhism traces its origins to Siddhartha Gautama, known as the Buddha, who taught the path to enlightenment, including the Four Noble Truths.` },
      { q:`A religion that involves belief in only one god is described as:`, ch:[`Polytheistic`,`Monotheistic`,`Atheistic`,`Animistic`], ans:1, exp:`Monotheism is the belief in the existence of a single, supreme god.` },
      { q:`A religion that involves belief in multiple gods is described as:`, ch:[`Monotheistic`,`Secular`,`Polytheistic`,`Agnostic`], ans:2, exp:`Polytheism is the belief in and worship of multiple gods or deities.` },
      { q:`Confucianism, an influential philosophy and ethical system from China, was founded by:`, ch:[`Confucius`,`Buddha`,`Laozi`,`Mencius`], ans:0, exp:`Confucianism, developed from the teachings of Confucius, emphasizes respect, social harmony, and proper conduct in relationships.` },
      { q:`A synagogue is the traditional place of worship for followers of:`, ch:[`Christianity`,`Islam`,`Judaism`,`Buddhism`], ans:2, exp:`A synagogue is a Jewish house of worship and community gathering place.` },
      { q:`A mosque is the traditional place of worship for followers of:`, ch:[`Hinduism`,`Islam`,`Judaism`,`Christianity`], ans:1, exp:`A mosque is the traditional Islamic place of worship and prayer.` },
      { q:`A church is the traditional place of worship most associated with:`, ch:[`Christianity`,`Islam`,`Judaism`,`Hinduism`], ans:0, exp:`A church is the traditional place of worship for followers of Christianity.` },
      { q:`Diwali, the "Festival of Lights," is a major celebration primarily associated with which religion?`, ch:[`Islam`,`Christianity`,`Hinduism`,`Judaism`], ans:2, exp:`Diwali is a major festival in Hinduism (also celebrated by some Sikhs and Jains) that symbolizes the victory of light over darkness.` },
    ]
  },
];
